// Logotipo de Wozial incrustado como data URI.
// La presentación se descarga y se comparte como archivo suelto: si el logo
// fuera una URL, se vería roto fuera del servidor.
// Origen: Wozial/assets/img/logo-wozial.png (545x194, blanco sobre transparente).

export const LOGO_WOZIAL_SRC = 'data:image/png;base64,';

export const LOGO_WOZIAL = `<img src="${LOGO_WOZIAL_SRC}" alt="Wozial" width="545" height="194" style="width:100%;height:auto;display:block;">`;
